'use strict';
/* The semantic workbench uses one canonical API. The older numeric tools stay in app.js. */
window.KnowledgeWorkbench = (() => {
  const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const copy = v => JSON.parse(JSON.stringify(v));
  const kinds = {entity:'业务对象',term:'术语',attribute:'业务属性',relation:'关系',metric:'指标',rule:'规则与职责',dataset:'数据集',field:'数据字段',mapping:'数据映射'};
  const statuses = {draft:'草稿',confirmed:'已确认',needs_review:'需复核',retired:'已停用',pending:'待处理',running:'处理中',review:'待核对',partial:'部分完成',failed:'失败',cancelled:'已取消',accepted:'已接纳',rejected:'已拒绝',deferred:'已暂缓',stale:'需重新核对',complete:'解析完成',needs_conversion:'待转换'};
  const relationTypes = {business:'业务关系',is_a:'分类属于',denotes:'术语指称',has_attribute:'拥有属性',measures:'衡量对象',applies_to:'规则适用',depends_on:'依赖定义',maps_to:'映射数据',physical_fk:'物理外键'};
  const propertyFields = {
    entity:[], term:[], dataset:[['source','物理表或视图']],
    attribute:[['value_type','值类型'],['unit','单位'],['values','枚举说明']],
    field:[['value_type','值类型'],['column','物理字段'],['unit','单位']],
    metric:[['grain','统计粒度'],['unit','单位'],['inclusions','包含范围'],['exclusions','排除范围'],['time_scope','业务时间范围'],['expression','计算表达式（如已有）']],
    rule:[['condition','成立前提'],['requirement','判断、职责或动作要求'],['exceptions','例外（未知请留空）']],
    relation:[['condition','适用条件'],['cardinality','已知基数']],
    mapping:[['transformation','映射、换算或过滤说明']]
  };
  let C, S = {assets:[],sources:[],groups:[],batches:[],problems:[],history:[],snapshots:[],layout:{}}, activePage = 'knowledge';
  const pending = new Map(), drafts = new Map(), taskTexts = new Map();
  const assetDrafts=new Map();
  let importDraft = {name:'业务说明.txt',text:'',domain:'',scope:'',source_id:'',distinct:false}, selectedFiles = [], importResults = [];
  let reviewPageIndex=0;const candidatePages=new Map(),refPools=new Map();
  let reviewFilter='pending', reviewBatch='', deliverySelection=new Set(), publishResult=null, publishExecution=false;
  let G={view:'business',mode:'graph',domain:'',kind:'',status:'',query:'',selected:null,limit:80,zoom:1,fixed:[],focus:null};
  let layoutUndo=[], drag=null, connection=null, dialog=null;
  const badge = value => `<span class="badge kw-status-${esc(value)}">${esc(statuses[value]||value||'未说明')}</span>`;
  const button = (label, action, attrs='', cls='') => `<button type="button" class="${cls}" data-kw="${action}" ${attrs}>${label}</button>`;
  const options = (items,value,blank='请选择') => (blank===null?'':`<option value="">${esc(blank)}</option>`)+items.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('');
  const field = (label,key,value='',multiline=false) => `<label>${esc(label)}${multiline?`<textarea data-field="${esc(key)}">${esc(value)}</textarea>`:`<input data-field="${esc(key)}" value="${esc(value)}">`}</label>`;
  const heading = (title,subtitle,actions='') => `<div class="page-head"><div><span class="eyebrow">SEMANTIC WORKSPACE</span><h1>${title}</h1><p class="sub">${subtitle}</p></div><div class="header-actions">${actions}</div></div>`;
  const empty = (title,detail,actions='') => `<div class="empty"><b>${title}</b><p>${detail}</p>${actions}</div>`;
  const asset = id => S.assets.find(a=>a.id===id);
  const nameOf = id => asset(id)?.name || id || '未指定';
  const byId = (collection,id) => (S[collection]||[]).find(x=>x.id===id);
  const uid = () => crypto.randomUUID();
  const fmt = value => typeof value==='object' && value!==null ? Object.entries(value).filter(([k,v])=>v!==null&&v!==''&&(!Array.isArray(v)||v.length)).map(([k,v])=>`${({page:'页',line:'行',start_line:'起始行',end_line:'结束行',line_start:'起始行',line_end:'结束行',headings:'章节',type:'内容类型',part:'部分',table:'表',columns:'列',column_start:'起始列',column_end:'结束列',sheet:'工作表',row:'行',column:'列',paragraph:'段落',statement:'语句',cell:'单元格'}[k]||k)} ${Array.isArray(v)?v.join(' / '):({text:'文本',ddl:'表结构',paragraph:'段落',cell:'单元格',foreign_key:'外键',column:'字段',table:'表'}[v]||v)}`).join(' · ') : String(value||'位置未说明');
  function configure(context) { C=context; }
  function update(state) {
    const first=!S.project_id; S={assets:[],sources:[],groups:[],batches:[],problems:[],history:[],snapshots:[],layout:{},...state};
    if(first)try{for(const [key,value] of JSON.parse(sessionStorage.getItem('kw-pending:'+S.project_id)||'[]')){pending.set(key,value);if(value.path==='edit'&&value.request.asset)assetDrafts.set(key.replace(/^edit:/,''),{asset:value.request.asset,declaration:'',baseRevision:value.request.revision});if(value.path==='review'&&value.request.group_id)drafts.set(value.request.group_id,{assets:value.request.assets||[],reason:value.request.reason||''});}}catch(_){}
    if(first)try{const saved=JSON.parse(localStorage.getItem('kw-view:'+S.project_id)||'null');if(saved)G={...G,...saved};}catch(_){}
  }
  function saveView(){try{localStorage.setItem('kw-view:'+S.project_id,JSON.stringify(G));}catch(_){}}
  function rerender(){const main=$('#main');if(!main)return;main.innerHTML=render(activePage);mount();}
  function persistPending(){
    try{const saved=[...pending].map(([key,op])=>{const value=copy(op);if(value.request.content_base64){delete value.request.content_base64;value.needsMaterial=true;}if(value.request.text?.length>200000){delete value.request.text;value.needsMaterial=true;}return [key,value];});sessionStorage.setItem('kw-pending:'+S.project_id,JSON.stringify(saved));}catch(_){C.notify('浏览器暂时无法保存提交恢复记录，请保持此页并先查询提交结果。');}
  }
  async function payloadSignature(payload){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(payload)));return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
  async function receiptFor(key){const op=pending.get(key);if(!op)return null;const result=await C.api('knowledge/operation/'+encodeURIComponent(op.request.operation_id));if(result.found){pending.delete(key);if(op.path==='edit')assetDrafts.delete(key.replace(/^edit:/,''));if(op.path==='review')drafts.delete(op.request.group_id);persistPending();if(op.path==='publish')publishResult=result.receipt.result;await C.reload();return result.receipt;}op.checked=true;persistPending();return null;}
  async function transact(key,path,payload,baseRevision) {
    const signature=await payloadSignature(payload);let op=pending.get(key);
    if(op){const receipt=await receiptFor(key);if(receipt){if(op.signature!==signature)throw Error('上次提交已完成并已读回；当前修改尚未提交，请对照最新结果后再次保存。');return receipt.result??receipt;}if(op.signature!==signature)throw Error('上次提交结果尚未确认。请到项目历史查询结果，或保持原输入重试；本次修改已保留。');op.request={...payload,revision:op.request.revision,operation_id:op.request.operation_id};op.needsMaterial=false;}
    else{op={signature,path,request:{...payload,revision:baseRevision??S.revision,operation_id:uid()}};pending.set(key,op);}
    persistPending();let response;
    try{response=await C.api('knowledge/'+path,op.request);}catch(e){if(e.status&&e.status<500){pending.delete(key);persistPending();}else e.message+='。提交结果尚未确认，请在项目历史先查询结果或重试原提交。';throw e;}
    pending.delete(key);if(op.path==='edit')assetDrafts.delete(key.replace(/^edit:/,''));if(op.path==='review')drafts.delete(op.request.group_id);persistPending();
    try{await C.reload();}catch(e){C.notify('操作已保存，但列表刷新失败：'+e.message+'。请刷新读取结果。');}
    return response.result??response;
  }
  function pendingHtml(){return pending.size?`<div class="notice warning"><b>${pending.size} 项提交尚待确认回执</b><p>输入与操作身份已保留；刷新页面不会自动重发。</p>${button('查询与恢复提交','go','data-page="history"','small')}</div>`:'';}
  function pendingRows(){return [...pending].map(([key,op])=>`<div class="gap"><div><b>${esc(({edit:'保存知识',review:'候选组处置',publish:'发布快照',import:'保存材料',merge:'合并身份',separate:'保持分离','review-source':'复核来源'}[op.path]||'知识维护')+' · '+(op.request.asset?.name||op.request.filename||op.request.group_id||''))}</b><p>${op.checked?'尚无完成回执；重试会沿用同一操作身份。':'先查询已保存结果，再决定是否重试。'}${op.needsMaterial?'原件需重新选择，不能在此自动重发。':''}</p></div><div class="row">${button('查询结果','pending-query',`data-key="${esc(key)}"`,'small')}${op.checked&&!op.needsMaterial?button('重试原提交','pending-retry',`data-key="${esc(key)}"`,'small'):''}</div></div>`).join('');}
  function resolveSource(id,revision,fragmentId,extractionId){
    const source=byId('sources',id);if(!source)throw Error('找不到这份来源，请刷新项目');
    const r=source.revisions?.find(x=>String(x.revision)===String(revision??source.current_revision));if(!r)throw Error('指定的来源修订不存在，不能改读最新修订');
    const parses=r.extractions?.length?r.extractions:[{id:null,parsed:r.parsed}];let extraction;
    if(extractionId){extraction=parses.find(x=>x.id===extractionId);if(!extraction)throw Error('指定的提取结果不存在，请修复依据身份');}
    else if(fragmentId){const matches=parses.filter(x=>x.parsed?.fragments?.some(f=>f.id===fragmentId));if(!matches.length)throw Error('原依据片段不存在，请修复来源定位');const values=matches.map(x=>x.parsed.fragments.find(f=>f.id===fragmentId));if(new Set(values.map(x=>JSON.stringify(x))).size>1)throw Error('多次提取的同名片段存在差异，请明确原依据的提取身份');extraction=matches[0];}
    else extraction=parses.find(x=>x.id===r.current_extraction)||parses.at(-1);
    const fragment=fragmentId?extraction?.parsed?.fragments?.find(f=>f.id===fragmentId):null;if(fragmentId&&!fragment)throw Error('指定提取结果中没有原依据片段');
    return {source,revision:{...r,parsed:extraction?.parsed||r.parsed},extraction_id:extraction?.id,fragment};
  }
  function issuesHtml(issues=[]){return issues.map(x=>`<div class="kw-publish-issue"><b>${esc(nameOf(x.asset_id||x.id)||'交付范围')}</b><p>${esc(x.message||x.code)}</p>${x.asset_id?button('定位并修正','locate',`data-id="${esc(x.asset_id)}"`,'small'):''}</div>`).join('');}
  function scopeHtml(m){if(!m)return '';const x=m.scope||{};return `<div class="notice"><b>${m.draft?'草稿快照':'确认快照'} · ${m.complete?'本范围完整':'仍有待补缺口'}</b><p>实际包含 ${(x.included_ids||[]).length} 项，自动补入 ${(x.dependency_ids||[]).length} 项必需依赖。</p><p>${x.include_execution?'附带数据映射与执行声明':'未附带执行声明；必要物理依赖仍保留'}。范围外 ${x.omitted_asset_count||0} 项。</p>${x.dependency_ids?.length?`<details><summary>查看补入依赖</summary><p>${esc(x.dependency_ids.map(nameOf).join('、'))}</p></details>`:''}${m.issues?.length?issuesHtml(m.issues):''}</div>`;}
  function evidenceHtml(evidence=[]) {
    if(!evidence.length)return '<p class="muted">尚无依据，可存草稿后补充。</p>';
    return evidence.map(e=>{
      if(e.type==='manual')return `<div class="kw-evidence"><span class="privacy">操作者声明 · ${esc(e.actor||'本地操作者')}</span><blockquote>${esc(e.quote||'')}</blockquote></div>`;
      let resolved;try{resolved=resolveSource(e.source_id,e.revision,e.fragment_id,e.extraction_id);}catch(error){return `<div class="kw-evidence error"><b>来源定位需修复</b><p>${esc(error.message)}</p><blockquote>${esc(e.quote)}</blockquote></div>`;}const {source,fragment}=resolved;
      return `<div class="kw-evidence"><div class="row between"><b>${esc(source?.name||e.source_id)}</b>${button('查看原文','source',`data-id="${esc(e.source_id)}" data-revision="${e.revision}" data-fragment="${esc(e.fragment_id||'')}" data-extraction="${esc(e.extraction_id||'')}"`,'quiet small')}</div><span class="privacy">修订 ${esc(e.revision)} · ${esc(fmt(fragment?.location))}</span><blockquote>${esc(e.quote||fragment?.text||'片段不可用')}</blockquote></div>`;
    }).join('');
  }
  function render(page){activePage=page;return pendingHtml()+({knowledge:materialsPage,review:reviewPage,graph:graphPage,publish:publishPage,history:historyPage}[page]||materialsPage)();}
  function mount(){$$('details.kw-candidate[open]').forEach(hydrateCandidate);if(activePage==='graph'){drawGraph();drawInspector();}if(dialog?.conflict)showConflict();}

  function materialsPage(){
    return heading('把知识带进来','从你已有的资料开始。先保留原文，再核对候选，逐步形成共同定义。',button('任务范围','legacy','data-page="home"','small')+button('手工建知识','create','','primary'))+
      `<div class="kw-summary">${[['资料来源',S.sources.length],['待核对组',S.groups.filter(g=>!g.superseded_by&&['pending','deferred','stale'].includes(g.status)).length],['已确认知识',S.assets.filter(a=>a.status==='confirmed').length]].map(([l,n])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}<div class="kw-summary-action">${button('打开语义图谱 →','go','data-page="graph"','quiet')}</div></div>`+
      `<div class="grid cols2"><section class="card"><h2>粘贴业务说明</h2><p class="sub">术语、口径、制度条款和你的解释，都可以先作为一份材料。</p><label>材料名称<input id="kw-import-name" data-import="name" value="${esc(importDraft.name)}"></label><label>业务领域<input id="kw-import-domain" data-import="domain" value="${esc(importDraft.domain)}" placeholder="例如：运输管理；可稍后补充"></label><label>适用范围<input id="kw-import-scope" data-import="scope" value="${esc(importDraft.scope)}" placeholder="例如：本次运输业务模型；未知可留空"></label><label>原文<textarea id="kw-import-text" data-import="text" rows="7" placeholder="粘贴一段业务知识，系统会保留这份原文及位置。">${esc(importDraft.text)}</textarea></label>${sourceChoice()}${button('保存材料','import-text','','primary')}<p id="kw-import-error" class="error" role="alert"></p></section>`+
      `<section class="card"><h2>上传已有资料</h2><p class="sub">DDL、文本、CSV / XLSX、DOCX、带文本层的 PDF，以及 YAML / JSON 模型。</p><div class="import-card"><label>选择文件（每份不超过 32 MB）<input id="kw-files" type="file" multiple accept=".txt,.md,.sql,.csv,.xlsx,.docx,.pdf,.yaml,.yml,.json"></label><p class="privacy">${selectedFiles.length?esc(selectedFiles.map(f=>f.name).join('、')):'原件留在本机；不执行文件中的脚本或外部链接。'}</p><details><summary>表格读取范围（CSV / XLSX）</summary><div class="grid cols2"><label>工作表名<input id="kw-sheet" placeholder="留空读取全部工作表"></label><label>表头行<input id="kw-header" type="number" min="1" value="1"></label></div><label>单元格范围<input id="kw-range" placeholder="例如 A1:F30；留空读取全部"></label></details>${button('导入所选文件','import-files','','primary')}</div><div id="kw-import-results">${importResults.map(r=>`<p class="${r.ok?'':'error'}">${esc(r.name)}：${esc(r.message)}</p>`).join('')}</div><div class="notice">扫描页或不能可靠解析的部分会单独列出；上传完成不代表业务含义已经确认。</div>${button('打开数值试算资料','legacy','data-page="data"','quiet small')}</section></div>`+
      `<div class="section-title"><h2>已有材料</h2><span class="privacy">选中原文，可查看解析位置与来源修订</span></div><div class="card">${S.sources.length?S.sources.map(sourceRow).join(''):empty('还没有材料','粘贴一段知识或上传一份表结构即可开始。')}</div>`+
      `<div class="section-title"><h2>处理任务</h2><span class="privacy">文本语义由当前宿主 Agent 协助整理</span></div><div class="card">${S.batches.length?S.batches.slice().reverse().map(batchRow).join(''):empty('等待第一份材料','材料保存后可准备 Agent 任务，也能手工录入知识。')}</div>`;
  }
  function sourceChoice(){return `<label>这次材料的来源<select id="kw-import-source" data-import="source_id">${options(S.sources.map(s=>[s.id,s.name]),importDraft.source_id,'作为新材料加入')}</select></label><label class="kw-inline-check"><input type="checkbox" data-import="distinct" ${importDraft.distinct?'checked':''}> 内容相同但出处不同，保留独立来源</label>`;}
  function sourceRow(s){const r=s.revisions?.find(x=>x.revision===s.current_revision)||s.revisions?.at(-1),p=r?.parsed||{};return `<div class="gap"><div><h3>${esc(s.name)} ${badge(p.status)}</h3><p>${esc(s.domain||'领域待说明')} · ${esc(s.format||p.format)} · 来源修订 ${esc(s.current_revision)} · ${p.fragments?.length||0} 个片段</p>${(p.warnings||[]).map(w=>`<p class="kw-warning">${esc(typeof w==='object'?w.message||fmt(w):w)}</p>`).join('')}</div><div class="row">${button('查看原文','source',`data-id="${esc(s.id)}"`,'small')}${button('更新材料','update-source',`data-id="${esc(s.id)}"`,'small')}</div></div>`;}
  function batchRow(b){const names=(b.sources||[]).map(r=>byId('sources',r.source_id)?.name||r.source_id).join('、');return `<div class="gap"><div><h3>${esc(names||'知识处理任务')} ${badge(b.status)}</h3><p class="privacy">${esc(b.id)} · ${esc(b.created||'')}</p>${taskTexts.has(b.id)?`<div class="kw-task"><b>等待宿主处理</b><p>把下面指令交给当前 Agent；候选返回后点击刷新，再进入核对。</p><textarea readonly aria-label="宿主处理指令">${esc(taskTexts.get(b.id))}</textarea>${button('复制指令','copy-task',`data-id="${esc(b.id)}"`,'small')}</div>`:''}</div><div class="row">${button('准备 Agent 任务','prepare',`data-id="${esc(b.id)}"`,'small')}${button('查看候选','batch-review',`data-id="${esc(b.id)}"`,'small')}${b.status==='cancelled'?button('恢复任务','resume',`data-id="${esc(b.id)}"`,'small'):button('取消任务','cancel-task',`data-id="${esc(b.id)}"`,'quiet small')}</div></div>`;}

  function reviewPage(){const groups=S.groups.filter(g=>(!reviewBatch||g.batch_id===reviewBatch)&&(reviewFilter==='all'||reviewFilter==='pending'?reviewFilter==='all'||(!g.superseded_by&&['pending','deferred','stale'].includes(g.status)):g.status===reviewFilter)).slice().reverse();reviewPageIndex=Math.min(reviewPageIndex,Math.max(0,Math.ceil(groups.length/10)-1));const visible=groups.slice(reviewPageIndex*10,reviewPageIndex*10+10),pages=Math.max(1,Math.ceil(groups.length/10));
    return heading('把候选变成共同定义','按一组相关变化核对当前定义、建议和原文。接纳前可以直接修正。',button('项目问题','legacy','data-page="issues"','small'))+
      `<div class="toolbar kw-toolbar"><label>处置状态<select id="kw-review-filter">${options([['pending','待处理与暂缓'],['accepted','已接纳'],['rejected','已拒绝'],['all','全部']],reviewFilter,null)}</select></label><label>处理批次<select id="kw-review-batch">${options(S.batches.map(b=>[b.id,(b.sources||[]).map(r=>byId('sources',r.source_id)?.name||r.source_id).join('、')||b.id]),reviewBatch,'所有批次')}</select></label><span class="spacer"></span><span class="privacy">${groups.length} 组变化</span></div>`+
      `<div class="row">${button('上一页组','review-page',`data-page-index="${reviewPageIndex-1}" ${reviewPageIndex===0?'disabled':''}`,'small')}<span class="privacy">第 ${reviewPageIndex+1} / ${pages} 页 · 每页最多 10 组</span>${button('下一页组','review-page',`data-page-index="${reviewPageIndex+1}" ${reviewPageIndex+1>=pages?'disabled':''}`,'small')}</div>${groups.length?visible.map(groupCard).join(''):empty('当前没有待核对变化','可以先加入资料并准备宿主任务，或手工创建知识。',button('加入资料','go','data-page="knowledge"','primary'))}`+
      `<div class="section-title"><h2>需复核的知识</h2></div><div class="card">${S.assets.filter(a=>a.status==='needs_review').map(a=>`<div class="gap"><div><h3>${esc(a.name)} ${badge(a.status)}</h3><p>${esc(a.definition)}</p></div>${button('对照来源并复核','review-source',`data-id="${esc(a.id)}"`,'small')}</div>`).join('')||'<p class="muted">没有来源更新引起的待复核知识。</p>'}</div>`;
  }
  function groupDraft(g){if(!drafts.has(g.id))drafts.set(g.id,{assets:g.candidates.map(c=>copy(c.asset||asset(c.target_id)||{})),reason:g.reason||''});return drafts.get(g.id);}
  function groupCard(g){const d=groupDraft(g),locked=!!g.superseded_by||['accepted','rejected'].includes(g.status),start=Math.min(candidatePages.get(g.id)||0,Math.max(0,Math.ceil(g.candidates.length/20)-1))*20;return `<section class="card kw-group" data-group="${esc(g.id)}"><div class="row between"><div><h2>${esc(g.summary||'候选变化')} ${badge(g.status)}</h2><p class="privacy">${g.candidates.length} 项变化 · ${esc(g.id)}</p></div>${button('刷新并核对当前状态','refresh','','quiet small')}${button('重新准备宿主任务','prepare',`data-id="${esc(g.batch_id)}"`,'quiet small')}</div>${g.superseded_by?`<div class="notice">此组已由新的候选组替代，仅保留核对历史。${button('查看接替候选','show-group',`data-id="${esc(g.superseded_by)}"`,'small')}</div>`:''}${g.reason?`<div class="notice">处置说明：${esc(g.reason)}</div>`:''}${candidatePager(g,start)}${g.candidates.slice(start,start+20).map((c,offset)=>{const i=start+offset;
      const a=d.assets[i],current=asset(c.target_id||a.id);return `<details class="kw-candidate" data-candidate-index="${i}" ${g.candidates.length<4?'open':''}><summary><span>${esc(kinds[a.kind]||c.op)} · ${esc(a.name||current?.name||c.target_id||'未命名')}</span><span class="privacy">${esc(c.op==='retire'?'建议停用':c.op==='merge'?'建议合并':current?'修改已有定义':'新增定义')}</span></summary><div class="kw-diff"><div><span class="eyebrow">当前</span>${current?`<h3>${esc(current.name)}</h3><p>${esc(current.definition)}</p><p class="privacy">${esc(current.domain||'领域未说明')} · ${esc(current.scope||'范围未说明')}</p>`:'<p class="muted">图谱中尚无对应资产</p>'}<p>${esc(c.reason||'')}</p>${evidenceHtml(c.evidence?.length?c.evidence:a.evidence)}</div><div><span class="eyebrow">${locked?'已处置候选':'候选 · 可直接修正'}</span><fieldset data-candidate="${i}" data-readonly="${locked}"></fieldset></div></div></details>`;}).join('')}${candidatePager(g,start)}<label>处置理由<textarea data-group-reason ${locked?'readonly':''} placeholder="拒绝或暂缓时说明原因；接纳时可记录判断。">${esc(d.reason)}</textarea></label><div class="row">${locked?'':button('接纳整组','review-action',`data-id="${esc(g.id)}" data-mode="accept"`,'primary')+button('暂缓','review-action',`data-id="${esc(g.id)}" data-mode="defer"`)+button('拒绝','review-action',`data-id="${esc(g.id)}" data-mode="reject"`,'danger')}<span class="privacy">接纳整组会写入全部 ${g.candidates.length} 项，包含未展开与其他页候选；请逐项展开核对。当前目标变化时请重新准备宿主任务。</span></div><p class="error kw-group-error" role="alert"></p></section>`;}

  function candidatePager(g,start){return g.candidates.length>20?`<div class="row kw-candidate-pages">${button('上一段候选','candidate-page',`data-id="${esc(g.id)}" data-offset="${start-20}" ${start===0?'disabled':''}`,'small')}<span class="privacy">本段 ${start+1}–${Math.min(start+20,g.candidates.length)} / 共 ${g.candidates.length} 项</span>${button('下一段候选','candidate-page',`data-id="${esc(g.id)}" data-offset="${start+20}" ${start+20>=g.candidates.length?'disabled':''}`,'small')}</div>`:'';}
  function hydrateCandidate(details){const holder=details.querySelector('[data-candidate]');if(!holder||holder.dataset.loaded)return;const g=byId('groups',details.closest('[data-group]').dataset.group),d=groupDraft(g);holder.innerHTML=assetFields(d.assets[Number(holder.dataset.candidate)],{candidate:true,extraAssets:d.assets});holder.dataset.loaded='true';if(holder.dataset.readonly==='true')holder.querySelectorAll('input:not(.kw-option-search),textarea,select').forEach(x=>x.disabled=true);}
  function captureGroups(){for(const group of $$('[data-group]')){const g=byId('groups',group.dataset.group),d=groupDraft(g);for(const holder of group.querySelectorAll('[data-candidate][data-loaded]'))d.assets[Number(holder.dataset.candidate)]=readAsset(holder,d.assets[Number(holder.dataset.candidate)]);d.reason=group.querySelector('[data-group-reason]').value;}}
  function referenceSelector(a,others){const key=uid(),selected=new Set(a.refs||[]),items=[...others,...(a.refs||[]).filter(id=>!others.some(x=>x.id===id)).map(id=>({id,name:nameOf(id),kind:'',domain:'待定位引用'}))];refPools.set(key,{items,selected,query:'',limit:100});return `<details class="kw-multiselect" data-ref-pool="${key}"><summary>必需引用 <span class="privacy kw-ref-count">已选 ${selected.size} 项</span></summary><input class="kw-option-search" placeholder="搜索知识名称" aria-label="搜索必需引用"><div class="kw-options"></div><div class="kw-reference-footer"></div></details>`;}
  function renderReferences(details){const p=refPools.get(details.dataset.refPool);if(!p)return;const matches=p.items.filter(x=>(x.name+' '+x.domain+' '+x.id).toLowerCase().includes(p.query));details.querySelector('.kw-options').innerHTML=matches.slice(0,p.limit).map(x=>`<label><input type="checkbox" data-ref="${esc(x.id)}" ${p.selected.has(x.id)?'checked':''} ${details.closest('[data-readonly="true"]')?'disabled':''}> ${esc(x.name)} <span class="privacy">${esc(kinds[x.kind]||'')} · ${esc(x.domain||'')}</span></label>`).join('')||'<p class="muted">没有匹配的可引用知识。</p>';details.querySelector('.kw-reference-footer').innerHTML=`<p class="privacy">显示 ${Math.min(matches.length,p.limit)} / ${matches.length} 项；未显示的已选引用仍保留。</p>${matches.length>p.limit?button('显示更多引用','refs-more',`data-pool="${esc(details.dataset.refPool)}"`,'small'):''}`;details.querySelector('.kw-ref-count').textContent='已选 '+p.selected.size+' 项';}
  function captureReference(el){if(!el.dataset.ref)return;const details=el.closest('[data-ref-pool]'),p=refPools.get(details?.dataset.refPool);if(p){el.checked?p.selected.add(el.dataset.ref):p.selected.delete(el.dataset.ref);details.querySelector('.kw-ref-count').textContent='已选 '+p.selected.size+' 项';}}
  function assetFields(a,{candidate=false,extraAssets=[]}={}) {
    const p=a.properties||{},kind=a.kind||'entity',pool=[...new Map([...S.assets,...extraAssets].filter(x=>x.id).map(x=>[x.id,x])).values()],others=pool.filter(x=>x.id!==a.id&&x.status!=='retired'),ends=pool.filter(x=>!['relation','mapping'].includes(x.kind)).map(x=>[x.id,`${x.name} · ${kinds[x.kind]||x.kind}`]);[a.from,a.to].filter(Boolean).forEach(id=>{if(!ends.some(x=>x[0]===id))ends.push([id,nameOf(id)]);});
    return `<div class="grid cols2"><label>知识类型<select data-field="kind" ${a.id?'disabled':''}>${options(Object.entries(kinds),kind,null)}</select></label>${field('名称','name',a.name)}</div>${field('定义','definition',a.definition,true)}<div class="grid cols2">${field('领域','domain',a.domain)}${field('适用范围','scope',a.scope)}</div>${field('别名（用逗号分隔）','aliases',(a.aliases||[]).join('，'))}`+
      (['relation','mapping'].includes(kind)?`<div class="grid cols2"><label>起点<select data-field="from">${options(ends,a.from)}</select></label><label>终点<select data-field="to">${options(ends,a.to)}</select></label></div><div class="grid cols2"><label>连接类型<select data-field="relation_type">${options(Object.entries(relationTypes),a.relation_type||(kind==='mapping'?'maps_to':'business'),null)}</select></label>${field('谓词（例如：监管、负责维护）','predicate',a.predicate)}</div><div data-physical ${a.relation_type==='physical_fk'?'':'hidden'}><p class="privacy">物理外键字段按顺序一一对应，用逗号分隔。</p><div class="grid cols2">${field('起点字段','properties.from_fields',(p.from_fields||[]).join('，'))}${field('终点字段','properties.to_fields',(p.to_fields||[]).join('，'))}</div></div>`:'')+
      `<div class="kw-property-fields">${(propertyFields[kind]||[]).map(([key,label])=>field(label,'properties.'+key,Array.isArray(p[key])?p[key].join('，'):p[key]||'',!['unit','value_type','source','column'].includes(key))).join('')}</div>`+
      `${referenceSelector(a,others)}<details><summary>有效期（未提供可留空）</summary><div class="grid cols2">${field('生效日期','effective_from',a.effective_from)}${field('截止日期','effective_to',a.effective_to)}</div></details>`;
  }
  function readAsset(container,original){const a=copy(original||{});if(!container||!container.querySelector('[data-field]'))return a;a.properties={...(a.properties||{})};container.querySelectorAll('[data-field]').forEach(el=>{const key=el.dataset.field;if(['properties.from_fields','properties.to_fields'].includes(key)){if(el.value.trim())a.properties[key.slice(11)]=el.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);else delete a.properties[key.slice(11)];}else if(key.startsWith('properties.'))a.properties[key.slice(11)]=el.value.trim();else if(key==='aliases')a.aliases=el.value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);else a[key]=el.value.trim();});const refPool=container.querySelector('[data-ref-pool]');a.refs=refPool?[...(refPools.get(refPool.dataset.refPool)?.selected||[])]:[...container.querySelectorAll('[data-ref]:checked')].map(el=>el.dataset.ref);return a;}

  function graphPage(){return heading('看清知识之间的关系','选择对象，沿关系核对定义和来源。图、表与详情读写同一份知识。',button('新建知识','create','','primary')+button('数值与明细核对','legacy','data-page="check"','small'))+
    `<div class="toolbar kw-toolbar"><div class="toggle">${[['business','业务'],['rules','指标与规则'],['data','数据映射'],['all','全部']].map(([v,l])=>button(l,'view',`data-view="${v}"`,G.view===v?'active':'')).join('')}</div><input id="kw-graph-search" value="${esc(G.query)}" placeholder="查找名称、别名或定义" aria-label="搜索图谱"><select id="kw-domain" aria-label="按领域筛选">${options([...new Set(S.assets.map(a=>a.domain).filter(Boolean))].map(v=>[v,v]),G.domain,'全部领域')}</select><select id="kw-kind" aria-label="按类型筛选">${options(Object.entries(kinds),G.kind,'全部类型')}</select><select id="kw-status" aria-label="按状态筛选">${options(['draft','confirmed','needs_review','retired'].map(v=>[v,statuses[v]]),G.status,'有效知识')}</select><span class="spacer"></span>${button(G.mode==='graph'?'表格视图':'图谱视图','toggle-view','','small')}</div>`+
    `<div class="kw-graph-layout"><section class="kw-graph-main">${G.mode==='graph'?`<div class="toolbar"><span id="kw-graph-count" class="privacy"></span><span class="spacer"></span>${button('−','zoom','data-delta="-0.15"','small')}${button('＋','zoom','data-delta="0.15"','small')}${button('整理布局','arrange','','small')}${button('撤销布局','undo-layout','','small')}${button(connection?'取消连线':'连接对象','connect','','small')}</div><div class="kw-canvas" id="kw-canvas"><svg id="kw-graph" aria-label="语义图谱，可拖动节点和连接端口"></svg></div><div class="graph-hint">拖节点调整布局 · 从圆点拖到目标建立关系 · 双击编辑 · 空白处拖动平移</div>`:`<div id="kw-asset-table"></div>`}<div class="kw-more">${button('显示更多','more','','quiet small')}${G.focus?button('退出邻域','clear-focus','','quiet small'):''}</div></section><aside class="kw-inspector" id="kw-inspector"></aside></div><div class="section-title"><h2>相关问题</h2></div><div class="card" id="kw-problems">${problemsHtml()}</div>`;}
  function filteredAssets(){let list=S.assets.filter(a=>(!G.domain||a.domain===G.domain)&&(!G.kind||a.kind===G.kind)&&(G.status?a.status===G.status:a.status!=='retired'));const allowed={business:['entity','term','attribute','relation'],rules:['entity','term','metric','rule','relation','attribute'],data:['entity','attribute','dataset','field','mapping','relation'],all:Object.keys(kinds)}[G.view];list=list.filter(a=>allowed.includes(a.kind)&&(!['business','rules'].includes(G.view)||a.relation_type!=='physical_fk'));if(G.query){const q=G.query.toLowerCase();list=list.filter(a=>[a.name,a.definition,a.domain,...(a.aliases||[])].join(' ').toLowerCase().includes(q));}if(G.focus){const ids=new Set([G.focus]);S.assets.forEach(a=>{if(a.from===G.focus||a.to===G.focus){ids.add(a.id);ids.add(a.from);ids.add(a.to);}if(a.id===G.focus)(a.refs||[]).forEach(x=>ids.add(x));if((a.refs||[]).includes(G.focus))ids.add(a.id);});list=list.filter(a=>ids.has(a.id));}return list;}
  function currentLayout(){const positions=copy(S.layout);graphData().nodes.forEach((a,i)=>{positions['semantic:'+G.view+':'+a.id]={...point(a,i)};});return positions;}
  function point(a,index){return S.layout['semantic:'+G.view+':'+a.id]||{x:40+(index%3)*260,y:40+Math.floor(index/3)*140};}
  function graphData(){const matched=filteredAssets(),visible=matched.slice(0,G.limit),ids=new Set(visible.map(a=>a.id));const edges=matched.filter(a=>['relation','mapping'].includes(a.kind)&&(ids.has(a.id)||(ids.has(a.from)&&ids.has(a.to))));edges.forEach(e=>{[e.from,e.to].forEach(id=>{if(id)ids.add(id);});});return {matched,nodes:S.assets.filter(a=>ids.has(a.id)&&!['relation','mapping'].includes(a.kind)),edges};}
  function drawGraph(){if(activePage!=='graph')return;const found=filteredAssets(),more=$('[data-kw="more"]');if(more)more.disabled=found.length<=G.limit;if(G.mode==='table'){$('#kw-asset-table').innerHTML=`<p class="privacy">共 ${found.length} 项，当前显示 ${Math.min(found.length,G.limit)} 项${found.length>G.limit?'；可继续加载更多。':'。'}</p><table><thead><tr><th>知识</th><th>领域 / 范围</th><th>定义</th><th>状态</th></tr></thead><tbody>${found.slice(0,G.limit).map(a=>`<tr data-kw="select" data-id="${esc(a.id)}" tabindex="0" class="${G.selected===a.id?'selected':''}"><td><b>${esc(a.name)}</b><small>${esc(kinds[a.kind])}</small></td><td>${esc(a.domain)}<small>${esc(a.scope)}</small></td><td>${esc(a.definition)}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table>${!found.length?empty('没有匹配的知识','调整筛选或加入新的材料。'):''}`;return;}
    const svg=$('#kw-graph');if(!svg)return;const {matched,nodes,edges}=graphData(),map=new Map(nodes.map((a,i)=>[a.id,{...point(a,i),a}]));const width=Math.max(850,...[...map.values()].map(p=>p.x+260)),height=Math.max(540,...[...map.values()].map(p=>p.y+140));svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.width=width*G.zoom+'px';svg.style.height=height*G.zoom+'px';$('#kw-graph-count').textContent=`${matched.length} 项匹配 · 当前 ${nodes.length} 个节点、${edges.length} 条关系`;
    svg.innerHTML=`<defs><marker id="kw-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#668f7b"/></marker></defs>`+edges.map(e=>{const a=map.get(e.from),b=map.get(e.to);if(!a||!b)return '';const self=e.from===e.to,path=self?`M${a.x+190},${a.y+30} C${a.x+285},${a.y-40} ${a.x+285},${a.y+130} ${a.x+190},${a.y+62}`:`M${a.x+210},${a.y+43} C${a.x+260},${a.y+43} ${b.x-50},${b.y+43} ${b.x},${b.y+43}`;return `<g class="kw-edge-group ${G.selected===e.id?'selected':''}" data-kw-edge="${esc(e.id)}" tabindex="0"><path class="kw-edge-hit" d="${path}"/><path class="kw-edge ${e.status==='needs_review'?'review':''}" d="${path}" marker-end="url(#kw-arrow)"/><text x="${self?a.x+235:(a.x+b.x+210)/2}" y="${self?a.y+20:(a.y+b.y)/2+34}" text-anchor="middle">${esc(e.predicate||relationTypes[e.relation_type]||'待定义')}</text></g>`;}).join('')+nodes.flatMap(a=>(a.refs||[]).map(id=>{const f=map.get(a.id),t=map.get(id);return f&&t?`<path class="kw-ref-edge" d="M${f.x+105},${f.y+88} L${t.x+105},${t.y}"/>`:'';})).join('')+nodes.map((a,i)=>{const p=point(a,i);return `<g data-kw-node="${esc(a.id)}" class="kw-node ${G.selected===a.id?'selected':''} status-${esc(a.status)}" transform="translate(${p.x},${p.y})" tabindex="0" role="button" aria-label="${esc(a.name)}"><rect width="210" height="90" rx="10"/><text x="14" y="24" class="kw-node-name">${esc(a.name.slice(0,16))}</text><text x="14" y="45">${esc(kinds[a.kind])} · ${esc(a.domain||'领域待说明')}</text><text x="14" y="69">${esc(statuses[a.status]||a.status)}${G.fixed.includes(a.id)?' · 已固定':''}</text><circle class="kw-port" cx="210" cy="43" r="6"/></g>`;}).join('')+(!nodes.length?'<text x="45" y="100" class="kw-empty-graph">加入知识或调整筛选后，在这里查看关系。</text>':'');
  }
  function drawInspector(){const el=$('#kw-inspector');if(!el)return;const a=asset(G.selected);if(!a){el.innerHTML=`<span class="eyebrow">知识详情</span><h2>${connection?'选择关系两端':'从一个对象开始'}</h2><p class="sub">${connection?'点击起点，再点击终点；也可以拖动节点右侧圆点。':'点击节点或关系查看定义和原文。双击可编辑，选择“展开邻域”只看与它相关的知识。'}</p>${button('手工创建知识','create','','primary small')}`;return;}
    const refs=S.assets.filter(x=>x.from===a.id||x.to===a.id||(x.refs||[]).includes(a.id));el.innerHTML=`<span class="eyebrow">${esc(kinds[a.kind])}</span><div class="row between"><h2>${esc(a.name)}</h2>${badge(a.status)}</div><p class="kw-definition">${esc(a.definition||'定义待补充')}</p><p class="privacy">${esc(a.domain||'领域待说明')} · ${esc(a.scope||'范围待说明')}</p><p class="privacy">${esc(a.id)}</p>${a.aliases?.length?`<p>别名：${esc(a.aliases.join('、'))}</p>`:''}<div class="row">${button('编辑定义','edit',`data-id="${esc(a.id)}"`,'primary small')}${button('展开邻域','focus',`data-id="${esc(a.id)}"`,'small')}${button(G.fixed.includes(a.id)?'取消固定':'固定位置','fix',`data-id="${esc(a.id)}"`,'small')}</div>${a.from?`<div class="notice">${esc(nameOf(a.from))} → ${esc(a.predicate)} → ${esc(nameOf(a.to))}</div>`:''}<dl class="kw-properties">${Object.entries(a.properties||{}).map(([k,v])=>`<dt>${esc((propertyFields[a.kind]||[]).find(x=>x[0]===k)?.[1]||k)}</dt><dd>${esc(Array.isArray(v)?v.join('、'):typeof v==='object'?fmt(v):v)}</dd>`).join('')}</dl><h3>原文与依据</h3>${evidenceHtml(a.evidence)}${a.status==='needs_review'?button('处理来源复核','review-source',`data-id="${esc(a.id)}"`,'primary small'):''}<details><summary>引用影响（${refs.length}）</summary>${refs.map(r=>button(esc(r.name||r.predicate),'select',`data-id="${esc(r.id)}"`,'quiet small')).join('')||'<p class="muted">没有其他知识引用此项。</p>'}</details>${(S.separations||[]).some(x=>x.left_id===a.id||x.right_id===a.id)?`<details><summary>已记录的身份分离判断</summary>${(S.separations||[]).filter(x=>x.left_id===a.id||x.right_id===a.id).map(x=>`<p><b>与 ${esc(nameOf(x.left_id===a.id?x.right_id:x.left_id))} 保持分离</b></p><p>${esc(x.reason)}</p>`).join('')}<p class="privacy">定义或范围变化后应重新核对此判断。</p></details>`:''}<div class="row kw-maintenance">${button('合并 / 保持分离','resolve-identity',`data-id="${esc(a.id)}"`,'small')}${button(a.status==='draft'?'删除草稿':'停用','retire',`data-id="${esc(a.id)}"`,'danger small')}</div>`;
  }
  function problemsHtml(){let p=S.problems||[];if(G.selected)p=p.filter(x=>[x.asset_id,x.id,...(x.asset_ids||[])].includes(G.selected));return p.length?p.map(x=>{const id=x.asset_id||x.asset_ids?.[0]||x.target_id;return `<div class="gap"><div><h3>${esc(x.message||x.detail||x.title||x.code||'需核对')}</h3><p>${esc(x.next||x.reason||'请查看相关定义与原文。')}</p></div>${id?button('定位知识','select',`data-id="${esc(id)}"`,'small'):''}</div>`;}).join(''):'<p class="muted">当前范围没有已报告问题。未发现问题不等于业务含义已被证明正确。</p>';}

  function publishPage(){const chosen=S.assets.filter(a=>deliverySelection.has(a.id));return heading('把确认的知识交出去','发布固定快照，或导出草稿讨论。调用方拿到的定义、关系和出处与这里一致。',button('私人项目备份','legacy','data-page="delivery"','small'))+
    `<div class="grid cols2"><section class="card"><h2>选择交付范围</h2><p class="sub">不勾选时交付全部业务语义；勾选后交付所选知识及必需依赖。数据集、字段、物理外键和映射默认只随必要依赖带出。</p><details class="kw-multiselect" open><summary id="kw-selected-count">已选 ${chosen.length} 项${!chosen.length?' · 全部业务语义':''}</summary><input id="kw-publish-search" class="kw-option-search" placeholder="搜索知识名称" aria-label="搜索交付知识"><div class="kw-options kw-delivery-options">${S.assets.map(a=>`<label data-option-label="${esc((a.name+' '+a.domain).toLowerCase())}"><input type="checkbox" data-publish-id="${esc(a.id)}" ${deliverySelection.has(a.id)?'checked':''}> ${esc(a.name)} <span class="privacy">${esc(kinds[a.kind])} · ${esc(a.domain)} · ${esc(statuses[a.status])}</span></label>`).join('')}</div></details><label class="kw-inline-check"><input id="kw-include-execution" type="checkbox" ${publishExecution?'checked':''}> 附带数据映射与执行声明</label><div class="notice">需复核、未确认的必需定义、已停用依赖或缺失依据会阻止确认发布。草稿会明确标识缺口。</div><div class="row">${button('发布确认快照','publish','','primary')}${button('导出草稿供讨论','publish','data-draft="true"')}</div><div id="kw-publish-error" class="error" role="alert"></div></section><section class="card"><h2>交付与调用</h2>${publishResult?`<div class="notice"><b>快照已保存</b><p>${esc(publishResult.snapshot_id||publishResult.manifest?.snapshot_id)}</p></div>${button('下载语义包','download',`data-url="${esc(publishResult.download_url||'/api/knowledge/download/'+publishResult.snapshot_id)}" data-filename="${esc(publishResult.filename||'semantic-package.zip')}"`,'primary')}${scopeHtml(publishResult.manifest)}<p>包内附独立读取命令和人工核验页。解压或通过只读工具打开即可使用。</p>`:'<p class="sub">确认快照包含模型、必要证据片段、清单、人工核验页和调用说明。</p><p>交给另一个 Agent 后，请它报告所用快照，先搜索、消歧，再读取定义和出处。</p>'}<div class="notice">旧快照保持不变。当前知识修改后，请发布新快照；离线文件不能自动知道有更新。</div><h3>本次选择</h3><p id="kw-selection-summary">${esc(chosen.length?chosen.map(a=>a.name).join('、'):'全部业务语义（自动补齐必需依赖）')}</p></section></div><div class="section-title"><h2>已保存快照</h2></div><div class="card">${(S.snapshots||[]).length?S.snapshots.slice().reverse().map(s=>`<div class="gap"><div><h3>${esc(s.snapshot_id||s.id)} ${badge(s.draft?'draft':'confirmed')}</h3><p class="privacy">来源修订 ${esc(s.source_revision??s.revision)}</p><details><summary>实际范围与缺口</summary>${scopeHtml(s)}</details></div>${button('下载','download',`data-url="/api/knowledge/download/${esc(s.snapshot_id||s.id)}" data-filename="${esc(s.filename||'semantic-package.zip')}"`,'small')}</div>`).join(''):empty('尚未发布','先核对知识，再生成可独立读取的语义包。')}</div>`;}
  function historyPage(){return heading('项目历史','知识修改保留修订；布局移动独立保存。撤回会新增修订，不抹掉历史。',button('数值验证历史','legacy','data-page="check"','small')+button('完整项目备份','legacy','data-page="delivery"','small'))+`${pending.size?`<section class="card"><h2>待确认提交</h2>${pendingRows()}</section>`:''}<section class="card"><table><thead><tr><th>修订</th><th>变化</th><th>时间 / 操作者</th><th></th></tr></thead><tbody>${(S.history||[]).map(h=>`<tr><td>${esc(h.revision)}</td><td>${esc(h.summary)}</td><td>${esc(h.created||'')}<small>${esc(h.actor||'')}</small></td><td>${button('检查并撤回','undo',`data-revision="${h.revision}"`,'small')}</td></tr>`).join('')}</tbody></table></section>`;}

  function openDialog(title,body,onSave,{confirmLabel='保存',draft=false,assetOriginal=null}={}) {
    let el=$('#kw-dialog');if(!el){el=document.createElement('dialog');el.id='kw-dialog';document.body.append(el);}
    dialog={id:uid(),onSave,baseRevision:S.revision,assetOriginal,conflict:false};
    el.innerHTML=`<form id="kw-form"><div class="dialog-head"><div><small>语义知识</small><h2>${esc(title)}</h2></div>${button('×','close-dialog','','quiet')}</div><div class="kw-dialog-body">${body}</div><div class="kw-dialog-error"><p id="kw-dialog-error" class="error" role="alert"></p><div id="kw-conflict"></div></div><footer><span class="spacer"></span>${button('取消','close-dialog')}${draft?'<button type="submit" value="draft">保存草稿</button>':''}${onSave?`<button type="submit" value="confirm" class="primary">${esc(confirmLabel)}</button>`:''}</footer></form>`;
    el.showModal();$('#kw-form').addEventListener('submit',async event=>{event.preventDefault();const buttons=[...el.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await dialog.onSave(event.submitter?.value!=='draft',dialog);el.close();dialog=null;}catch(e){$('#kw-dialog-error').textContent=e.message;if(e.status===409){dialog.conflict=true;showConflict();}}finally{buttons.forEach(b=>b.disabled=false);}});
  }
  function showConflict(){const el=$('#kw-conflict');if(el)el.innerHTML='<p class="privacy">输入已保留。先刷新并查看最新定义，再决定如何继续。</p>'+button('读取最新状态并核对','dialog-refresh','','small');}
  function openAsset(id,prefill={}) {const draftKey=id||'new:'+JSON.stringify(prefill),savedDraft=assetDrafts.get(draftKey);const original=copy(savedDraft?.asset||asset(id)||{kind:'entity',name:'',definition:'',domain:importDraft.domain||'',scope:importDraft.scope||'',aliases:[],properties:{},refs:[],evidence:[],...prefill});openDialog(id?'编辑 '+original.name:'创建知识',`<div id="kw-asset-fields">${assetFields(original)}</div><h3>已有依据</h3>${evidenceHtml(original.evidence)}<label>本次声明或修正依据<textarea id="kw-manual-evidence" placeholder="用具体业务说明记录本次手工输入的依据；不会伪装成原材料中的文字。">${esc(savedDraft?.declaration||'')}</textarea></label>`,async(confirmed,d)=>{const changed=readAsset($('#kw-asset-fields'),original),declaration=$('#kw-manual-evidence').value.trim();if(declaration)changed.evidence=[...(changed.evidence||[]),{type:'manual',quote:declaration,actor:'local'}];const saved=await transact('edit:'+draftKey,'edit',{asset:changed,confirm:confirmed},d.baseRevision);G.selected=saved.asset_id||changed.id||null;assetDrafts.delete(draftKey);if(activePage==='graph'){drawGraph();drawInspector();}C.notify(confirmed?'知识已保存并确认':'草稿已保存');},{confirmLabel:'保存并确认',draft:true,assetOriginal:original});dialog.assetDraftKey=draftKey;if(savedDraft?.baseRevision!==undefined)dialog.baseRevision=savedDraft.baseRevision;}
  function openSource(id,revision,fragmentId,extractionId){const resolved=resolveSource(id,revision||undefined,fragmentId||undefined,extractionId||undefined),s=resolved.source,r=resolved.revision;let viewer=$('#kw-source-dialog');if(!viewer){viewer=document.createElement('dialog');viewer.id='kw-source-dialog';document.body.append(viewer);}viewer.innerHTML=`<div class="dialog-head"><h2>${esc(s.name)}</h2>${button('×','close-source','','quiet')}</div><div class="kw-dialog-body"><div class="row"><b>来源修订 ${esc(r?.revision)}</b>${badge(r?.parsed?.status)}<span class="privacy">${esc(s.id)}</span></div><div class="row">${(s.revisions||[]).map(x=>button('修订 '+x.revision,'source-version',`data-id="${esc(id)}" data-revision="${x.revision}"`,'small')).join('')}${(r.extractions||[]).length>1?r.extractions.map((x,i)=>button('提取 '+(i+1),'source-version',`data-id="${esc(id)}" data-revision="${r.revision}" data-extraction="${esc(x.id)}"`,'small')).join(''):''}${r?.attachment_id?button('下载原件','download',`data-url="/api/knowledge/source/${esc(r.attachment_id)}" data-filename="${esc(s.name)}"`,'small'):''}</div>${(r?.parsed?.warnings||[]).map(w=>`<div class="notice warning">${esc(typeof w==='object'?w.message||fmt(w):w)}</div>`).join('')}<div class="kw-fragments">${(r?.parsed?.fragments||[]).map(f=>`<section class="kw-fragment ${f.id===fragmentId?'target':''}" id="fragment-${esc(f.id)}"><h3>${esc(fmt(f.location))}</h3><pre>${esc(f.text)}</pre></section>`).join('')||'<p>这份修订没有可读取的文本片段，请查看解析结果或补充可读资料。</p>'}</div></div><footer>${button('关闭原文','close-source')}</footer>`;if(!viewer.open)viewer.showModal();if(fragmentId)viewer.querySelector('.kw-fragment.target')?.scrollIntoView({block:'center'});}

  async function importText(){const text=$('#kw-import-text').value;if(!text.trim())throw Error('请先填写材料原文');const payload={filename:importDraft.name||'业务说明.txt',text,domain:importDraft.domain,scope:importDraft.scope,...(importDraft.source_id?{source_id:importDraft.source_id}:{}),distinct_source:importDraft.distinct};const r=await transact('text-import','import',payload);importDraft.text='';importDraft.source_id='';rerender();C.notify('材料已保存。请准备 Agent 任务或核对结构候选。');return r;}
  async function importFiles(){if(!selectedFiles.length)throw Error('请先选择文件');if(importDraft.source_id&&selectedFiles.length>1)throw Error('更新一份来源时请只选择一个文件；多份新材料请改为新来源');const config={sheet:$('#kw-sheet')?.value||undefined,header:Number($('#kw-header')?.value||1),range:$('#kw-range')?.value||undefined};importResults=[];const succeeded=[];for(const file of selectedFiles){if(file.size>32*1024*1024){importResults.push({name:file.name,ok:false,message:'超过 32 MB，请缩小文件后重试'});continue;}try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await transact('file:'+file.name,'import',{filename:file.name,content_base64:btoa(binary),domain:importDraft.domain,scope:importDraft.scope,source_id:importDraft.source_id||undefined,distinct_source:importDraft.distinct,options:config});succeeded.push(file);importResults.push({name:file.name,ok:true,message:'已保存，请查看解析范围与候选'});}catch(e){importResults.push({name:file.name,ok:false,message:e.message});}}selectedFiles=selectedFiles.filter(f=>!succeeded.includes(f));rerender();}
  async function download(url,filename){if(url.startsWith('/api/knowledge/download/')){const link=document.createElement('a');link.href=url;link.download=filename||'semantic-package.zip';document.body.append(link);link.click();link.remove();C.notify('下载请求已发出，请查看浏览器保存结果');return;}const result=await fetch(url,{headers:{'X-Workbench-Token':$('meta[name="session-token"]').content}});if(!result.ok){let body;try{body=await result.json();}catch(_){}throw Error(body?.error||'下载失败，请重试');}const object=URL.createObjectURL(await result.blob()),a=document.createElement('a');a.href=object;a.download=filename||'semantic-package.zip';a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(object),60000);C.notify('下载请求已发出，请查看浏览器保存结果');}
  async function act(b){const a=b.dataset.kw,id=b.dataset.id;
    if(a==='show-group'){const g=byId('groups',id);if(!g)throw Error('接替候选尚未读回，请刷新项目');reviewBatch=g.batch_id;reviewFilter='all';const groups=S.groups.filter(x=>x.batch_id===reviewBatch).slice().reverse();reviewPageIndex=Math.floor(groups.findIndex(x=>x.id===id)/10);C.go('review');$('[data-group="'+id+'"]')?.scrollIntoView({block:'start'});return;}
    if(a==='review-page'){captureGroups();reviewPageIndex=Number(b.dataset.pageIndex);rerender();return;}
    if(a==='candidate-page'){captureGroups();candidatePages.set(id,Number(b.dataset.offset)/20);rerender();return;}
    if(a==='refs-more'){const pool=refPools.get(b.dataset.pool);if(pool){pool.limit+=100;renderReferences($('[data-ref-pool="'+b.dataset.pool+'"]'));}return;}
    if(a==='pending-query'){const result=await receiptFor(b.dataset.key);rerender();C.notify(result?'已读取上次完成结果，没有重复执行':'尚无完成回执；可重试原提交，系统仍会防重复');return;}
    if(a==='pending-retry'){const op=pending.get(b.dataset.key);if(!op||op.needsMaterial)throw Error('请从材料入口重新选择同一原件');const {revision,operation_id,...payload}=op.request;await transact(b.dataset.key,op.path,payload,revision);rerender();C.notify('已确认原提交的结果');return;}
    if(a==='locate'){G.selected=id;G.view='all';G.query='';G.kind='';G.status='';G.domain='';G.focus=null;saveView();return C.go('graph');}
    if(a==='go'||a==='legacy')return C.go(b.dataset.page);
    if(a==='refresh')return C.reload();
    if(a==='close-source'){$('#kw-source-dialog').close();return;}
    if(a==='close-dialog'){$('#kw-dialog').close();dialog=null;return;}
    if(a==='create')return openAsset(null);
    if(a==='edit')return openAsset(id);
    if(a==='source'||a==='source-version')return openSource(id,b.dataset.revision,b.dataset.fragment,b.dataset.extraction);
    if(a==='update-source'){const source=byId('sources',id);importDraft={...importDraft,source_id:id,name:source.name,domain:source.domain||'',scope:source.scope||'',text:''};C.go('knowledge');$('#kw-import-source').focus();C.notify('已选更新来源。粘贴新原文或选择新文件。');return;}
    if(a==='import-text')return importText();
    if(a==='import-files')return importFiles();
    if(a==='prepare'){const r=await transact('prepare:'+id,'task',{batch_id:id,action:'prepare'});taskTexts.set(id,r.host_instruction||`请使用 ai-data-delivery 处理项目「${S.project_directory||S.document?.name||S.project_id}」的批次 ${id}。读取本批次原文及现有知识，提出带来源的候选并提交；不要将推测写成已确认知识。`);if(activePage!=='knowledge')C.go('knowledge');else rerender();return;}
    if(a==='copy-task'){const value=taskTexts.get(id);try{await navigator.clipboard.writeText(value);C.notify('宿主指令已复制');}catch(_){b.closest('.kw-task').querySelector('textarea').select();C.notify('已选中指令，请按 Ctrl+C 复制');}return;}
    if(a==='cancel-task'||a==='resume'){await transact('task:'+id,'task',{batch_id:id,action:a==='resume'?'resume':'cancel'});C.notify(a==='resume'?'任务已恢复，可继续剩余范围':'任务已取消，已返回候选仍保留');return;}
    if(a==='batch-review'){reviewPageIndex=0;reviewBatch=id;reviewFilter='all';return C.go('review');}
    if(a==='review-action'){const g=byId('groups',id),el=b.closest('[data-group]'),d=groupDraft(g);d.assets=g.candidates.map((c,i)=>readAsset(el.querySelector(`[data-candidate="${i}"]`),d.assets[i]));d.reason=el.querySelector('[data-group-reason]').value;await transact('group:'+id,'review',{group_id:id,action:b.dataset.mode,reason:d.reason,assets:d.assets});drafts.delete(id);C.notify('本组处置已保存');return;}
    if(a==='select'){G.selected=id;saveView();drawGraph();drawInspector();if($('#kw-problems'))$('#kw-problems').innerHTML=problemsHtml();return;}
    if(a==='view'){G.view=b.dataset.view;G.limit=80;G.focus=null;connection=null;saveView();rerender();return;}
    if(a==='toggle-view'){G.mode=G.mode==='graph'?'table':'graph';saveView();rerender();return;}
    if(a==='focus'){G.focus=id;G.limit=80;G.query='';saveView();rerender();return;}
    if(a==='clear-focus'){G.focus=null;rerender();return;}
    if(a==='more'){G.limit+=80;drawGraph();return;}
    if(a==='fix'){G.fixed=G.fixed.includes(id)?G.fixed.filter(x=>x!==id):[...G.fixed,id];saveView();drawGraph();drawInspector();return;}
    if(a==='zoom'){G.zoom=Math.max(.4,Math.min(2,G.zoom+Number(b.dataset.delta)));saveView();drawGraph();return;}
    if(a==='arrange'){const before=currentLayout();graphData().nodes.forEach((x,i)=>{if(!G.fixed.includes(x.id))S.layout['semantic:'+G.view+':'+x.id]={x:40+(i%3)*260,y:40+Math.floor(i/3)*140};});try{await C.api('layout',{positions:S.layout});layoutUndo.push(before);}catch(e){S.layout=before;drawGraph();throw e;}drawGraph();return;}
    if(a==='undo-layout'){if(!layoutUndo.length)throw Error('当前会话没有可撤销的布局操作');const old=layoutUndo.at(-1);await C.api('layout',{positions:old});S.layout=old;layoutUndo.pop();drawGraph();return;}
    if(a==='connect'){connection=connection?null:{start:null};rerender();return;}
    if(a==='download')return download(b.dataset.url,b.dataset.filename);
    if(a==='publish'){publishResult=await transact('publish','publish',{asset_ids:[...deliverySelection],draft:b.dataset.draft==='true',include_execution:publishExecution});rerender();C.notify('快照已保存，可下载回读');return;}
    if(a==='undo'){if(!confirm('检查并撤回这一语义事务？有后续冲突时会保留当前内容并提示。'))return;await transact('undo:'+b.dataset.revision,'undo',{target_revision:Number(b.dataset.revision)});C.notify('语义事务已撤回，历史仍保留');return;}
    if(a==='retire')return retireDialog(id);
    if(a==='resolve-identity')return identityDialog(id);
    if(a==='review-source')return sourceReviewDialog(id);
    if(a==='dialog-refresh'){const current=dialog;await C.reload();const latest=asset(current.assetOriginal?.id);$('#kw-conflict').innerHTML=`<div class="notice"><b>最新定义</b><p>${esc(latest?.definition||'对象已不存在或此次操作不绑定单个对象')}</p><p>项目修订 ${S.revision}。上方输入未被覆盖，请对照后继续。</p></div>${button('已核对最新状态，继续使用保留输入','dialog-rebase','','small')}`;return;}
    if(a==='dialog-rebase'){dialog.baseRevision=S.revision;if(assetDrafts.has(dialog.assetDraftKey))assetDrafts.get(dialog.assetDraftKey).baseRevision=S.revision;dialog.conflict=false;$('#kw-conflict').innerHTML='<p class="privacy">已按当前修订继续；提交时仍会重检。</p>';return;}
  }
  function retireDialog(id){const a=asset(id);openDialog((a.status==='draft'?'删除或停用 ':'停用 ')+a.name,`<p>系统会检查所有引用，包含当前图上隐藏的知识。</p><label>处理方式<select id="kw-retire-mode">${options([['retire','停用并保留历史'],...(a.status==='draft'?[['delete','删除未引用、未发布的草稿']]:[])],'retire',null)}</select></label><label>原因<textarea id="kw-retire-reason"></textarea></label>`,async(_,d)=>{await transact('retire:'+id,'retire',{asset_id:id,reason:$('#kw-retire-reason').value,action:$('#kw-retire-mode').value},d.baseRevision);C.notify('处理已保存');},{confirmLabel:'确认处理',assetOriginal:a});}
  function identityDialog(id){const a=asset(id);openDialog('核对身份：'+a.name,`<p>先选另一对象并比较定义。合并会更新引用；保持分离会保存两者不同的理由。</p><label>另一项知识<select id="kw-identity-target">${options(S.assets.filter(x=>x.id!==id&&x.kind===a.kind&&x.status!=='retired').map(x=>[x.id,`${x.name} · ${x.domain}`]),'')}</select></label><div id="kw-identity-comparison"></div><label>处理方式<select id="kw-identity-mode">${options([['separate','保持分离'],['merge','合并到当前对象（保留当前 ID）']],'separate',null)}</select></label><details id="kw-merged-fields" hidden open><summary>合并后的完整定义（逐项核对）</summary>${assetFields(a)}</details><label>判断理由<textarea id="kw-identity-reason"></textarea></label>`,async(_,d)=>{const other=$('#kw-identity-target').value,reason=$('#kw-identity-reason').value;if(!other)throw Error('请选择另一项知识');if(!reason.trim())throw Error('请说明身份判断的理由');if($('#kw-identity-mode').value==='separate')await transact('identity:'+id,'separate',{left_id:id,right_id:other,reason},d.baseRevision);else {const otherAsset=asset(other),resolved=readAsset($('#kw-merged-fields'),a);resolved.aliases=[...new Set([...(resolved.aliases||[]),otherAsset.name,...(otherAsset.aliases||[])])];resolved.evidence=[...(a.evidence||[]),...(otherAsset.evidence||[])];await transact('identity:'+id,'merge',{survivor_id:id,merged_id:other,resolved_asset:resolved,reason},d.baseRevision);}C.notify('身份判断已保存');},{confirmLabel:'保存身份判断',assetOriginal:a});}
  function sourceReviewDialog(id){const a=asset(id);openDialog('复核来源：'+a.name,`<h3>原定义</h3><p>${esc(a.definition)}</p>${evidenceHtml(a.evidence)}<h3>来源的新修订</h3>${[...new Map((a.evidence||[]).filter(e=>e.source_id).map(e=>[e.source_id,e])).values()].map(e=>{const s=byId('sources',e.source_id),r=s?.revisions?.find(v=>v.revision===s.current_revision);return `<details open><summary>${esc(s?.name)} · 修订 ${esc(r?.revision)}</summary>${(r?.parsed?.fragments||[]).map(f=>`<label class="kw-source-choice"><input type="checkbox" data-new-evidence="${esc(JSON.stringify({source_id:s.id,revision:r.revision,extraction_id:r.current_extraction,fragment_id:f.id,quote:f.text}))}"><b>${esc(fmt(f.location))}</b><blockquote>${esc(f.text)}</blockquote></label>`).join('')}</details>`;}).join('')}<label>复核决定<select id="kw-source-action">${options([['retain','原定义仍适用，保留原依据'],['adopt','采用来源修订并调整定义']],'retain',null)}</select></label><div id="kw-source-asset" hidden>${assetFields(a)}</div><label>复核理由<textarea id="kw-source-reason" placeholder="说明原定义为何仍适用，或本次采用了什么变化。"></textarea></label>`,async(_,d)=>{const action=$('#kw-source-action').value,reason=$('#kw-source-reason').value,changed=readAsset($('#kw-source-asset'),a);if(!reason.trim())throw Error('请填写复核理由');if(action==='adopt'){const selected=[...$('#kw-dialog').querySelectorAll('[data-new-evidence]:checked')].map(x=>JSON.parse(x.dataset.newEvidence));if(!selected.length)throw Error('采用修订时，请勾选本次定义实际使用的新原文片段');const selectedSources=new Set(selected.map(e=>e.source_id));changed.evidence=[...(a.evidence||[]).filter(e=>!e.source_id||(!selectedSources.has(e.source_id)&&e.revision===byId('sources',e.source_id)?.current_revision)),...selected];}await transact('source-review:'+id,'review-source',{asset_id:id,action,reason,...(action==='adopt'?{asset:changed}:{})},d.baseRevision);C.notify('来源复核已保存');},{confirmLabel:'保存复核结论',assetOriginal:a});}

  document.addEventListener('toggle',e=>{if(!e.target.open)return;if(e.target.matches('.kw-candidate'))hydrateCandidate(e.target);if(e.target.matches('[data-ref-pool]'))renderReferences(e.target);},true);
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-kw]');if(!b)return;try{b.disabled=true;await act(b);}catch(err){const target=b.closest('[data-group]')?.querySelector('.kw-group-error')||(['import-text','import-files'].includes(b.dataset.kw)?$('#kw-import-error'):b.dataset.kw==='publish'?$('#kw-publish-error'):$('#kw-dialog[open] #kw-dialog-error'));if(target){target.textContent=err.message;const issues=err.details?.details?.issues||err.details?.issues;if(issues?.length)target.insertAdjacentHTML('beforeend',issuesHtml(issues));}else C.notify(err.message);}finally{b.disabled=false;}});
  document.addEventListener('input',e=>{const el=e.target;captureReference(el);if(dialog?.assetDraftKey!==undefined&&el.closest('#kw-form'))assetDrafts.set(dialog.assetDraftKey,{asset:readAsset($('#kw-asset-fields'),dialog.assetOriginal),declaration:$('#kw-manual-evidence').value,baseRevision:dialog.baseRevision});if(el.dataset.import){importDraft[el.dataset.import]=el.type==='checkbox'?el.checked:el.value;}
    if(el.matches('.kw-option-search')){const q=el.value.toLowerCase(),details=el.closest('.kw-multiselect');if(details.dataset.refPool){const pool=refPools.get(details.dataset.refPool);pool.query=q;pool.limit=100;renderReferences(details);}else details.querySelectorAll('[data-option-label]').forEach(x=>x.hidden=!x.dataset.optionLabel.includes(q));}
    if(el.id==='kw-graph-search'){G.query=el.value;G.limit=80;saveView();drawGraph();}
    const group=el.closest('[data-group]');if(group){const g=byId('groups',group.dataset.group),d=groupDraft(g),f=el.closest('[data-candidate]');if(f)d.assets[Number(f.dataset.candidate)]=readAsset(f,d.assets[Number(f.dataset.candidate)]);if(el.hasAttribute('data-group-reason'))d.reason=el.value;}
  });
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.import)importDraft[el.dataset.import]=el.type==='checkbox'?el.checked:el.value;if(el.id==='kw-files'){selectedFiles=[...el.files];return;}if(el.dataset.publishId){el.checked?deliverySelection.add(el.dataset.publishId):deliverySelection.delete(el.dataset.publishId);const chosen=S.assets.filter(a=>deliverySelection.has(a.id));$('#kw-selected-count').textContent='已选 '+chosen.length+' 项'+(!chosen.length?' · 全部业务语义':'');$('#kw-selection-summary').textContent=chosen.length?chosen.map(a=>a.name).join('、'):'全部业务语义（自动补齐必需依赖）';return;}if(el.id==='kw-include-execution')publishExecution=el.checked;
    if(el.dataset.field==='relation_type'){const holder=el.closest('[data-candidate],#kw-asset-fields,#kw-source-asset,#kw-merged-fields');if(holder?.querySelector('[data-physical]'))holder.querySelector('[data-physical]').hidden=el.value!=='physical_fk';}
    if(el.id==='kw-source-action')$('#kw-source-asset').hidden=el.value!=='adopt';
    if(el.id==='kw-review-filter'){reviewPageIndex=0;reviewFilter=el.value;rerender();}if(el.id==='kw-review-batch'){reviewPageIndex=0;reviewBatch=el.value;rerender();}
    const graphField={'kw-domain':'domain','kw-kind':'kind','kw-status':'status'}[el.id];if(graphField){G[graphField]=el.value;G.limit=80;saveView();drawGraph();}
    if(dialog?.assetDraftKey!==undefined&&el.closest('#kw-form'))assetDrafts.set(dialog.assetDraftKey,{asset:readAsset($('#kw-asset-fields'),dialog.assetOriginal),declaration:$('#kw-manual-evidence').value,baseRevision:dialog.baseRevision});
    if(el.matches('#kw-asset-fields [data-field="kind"]')){const a=readAsset($('#kw-asset-fields'),dialog.assetOriginal);$('#kw-asset-fields').innerHTML=assetFields(a);}
    if(el.id==='kw-identity-mode')$('#kw-merged-fields').hidden=el.value!=='merge';
    if(el.id==='kw-identity-target'){const a=asset(el.value);$('#kw-identity-comparison').innerHTML=a?`<div class="notice"><b>${esc(a.name)} · ${esc(a.domain)}</b><p>${esc(a.definition)}</p><p>范围：${esc(a.scope)}</p><dl>${Object.entries(a.properties||{}).map(([k,v])=>`<dt>${esc((propertyFields[a.kind]||[]).find(x=>x[0]===k)?.[1]||k)}</dt><dd>${esc(typeof v==='object'?fmt(v):v)}</dd>`).join('')}</dl><p>引用此项的定义：${S.assets.filter(x=>x.from===a.id||x.to===a.id||(x.refs||[]).includes(a.id)).length} 项</p></div>`:'';}
  });
  function svgPoint(e){const s=$('#kw-graph'),p=s.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(s.getScreenCTM().inverse());}
  function connect(start,end){connection=null;const a=asset(start),b=asset(end);if(!a||!b)return;openAsset(null,{kind:'relation',from:start,to:end,domain:a.domain||b.domain||'',scope:a.scope||'',relation_type:'business'});}
  document.addEventListener('pointerdown',e=>{if(!e.target.closest('#kw-graph'))return;const node=e.target.closest('[data-kw-node]'),edge=e.target.closest('[data-kw-edge]');if(edge){G.selected=edge.dataset.kwEdge;drawGraph();drawInspector();return;}if(!node){const c=$('#kw-canvas');drag={pan:true,x:e.clientX,y:e.clientY,left:c.scrollLeft,top:c.scrollTop};return;}const id=node.dataset.kwNode;G.selected=id;saveView();if(connection){if(connection.start)connect(connection.start,id);else{connection.start=id;C.notify('再选择关系的终点');}drawInspector();return;}const item=asset(id),nodes=graphData().nodes;drag={id,start:svgPoint(e),base:point(item,nodes.indexOf(item)),port:e.target.classList.contains('kw-port'),moved:false,before:currentLayout()};e.preventDefault();drawInspector();node.classList.add('selected');});
  document.addEventListener('pointermove',e=>{if(!drag||!$('#kw-graph'))return;if(drag.pan){const c=$('#kw-canvas');c.scrollLeft=drag.left+drag.x-e.clientX;c.scrollTop=drag.top+drag.y-e.clientY;return;}const p=svgPoint(e);drag.moved=drag.moved||Math.abs(p.x-drag.start.x)+Math.abs(p.y-drag.start.y)>4;if(drag.port){$('#kw-temp-edge')?.remove();$('#kw-graph').insertAdjacentHTML('beforeend',`<path id="kw-temp-edge" d="M${drag.base.x+210},${drag.base.y+43} L${p.x},${p.y}" stroke="#176c56" fill="none" stroke-dasharray="5 4" pointer-events="none"/>`);}else if(drag.moved){S.layout['semantic:'+G.view+':'+drag.id]={x:Math.max(8,drag.base.x+p.x-drag.start.x),y:Math.max(8,drag.base.y+p.y-drag.start.y)};drawGraph();}});
  document.addEventListener('pointerup',async e=>{if(!drag)return;const d=drag;drag=null;$('#kw-temp-edge')?.remove();if(d.pan)return;if(d.port){const end=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-kw-node]')?.dataset.kwNode;if(end)connect(d.id,end);}else if(d.moved){try{await C.api('layout',{positions:S.layout});layoutUndo.push(d.before);}catch(err){S.layout=d.before;drawGraph();C.notify('布局未保存，已恢复原位置：'+err.message);}}else drawGraph();});
  document.addEventListener('dblclick',e=>{const node=e.target.closest('[data-kw-node]'),edge=e.target.closest('[data-kw-edge]');if(node||edge)openAsset(node?.dataset.kwNode||edge.dataset.kwEdge);});
  document.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const node=e.target.closest('[data-kw-node]'),edge=e.target.closest('[data-kw-edge]');if(node||edge){e.preventDefault();openAsset(node?.dataset.kwNode||edge.dataset.kwEdge);}});
  return {configure,update,render,mount};
})();
